import threading
import queue
from typing import Callable, Any


class QueueWorker:
    """Worker that processes items from a queue in a background thread."""

    def __init__(self, callback: Callable[[Any], None], q: queue.Queue = None):
        self.callback = callback
        self.queue = q or queue.Queue()
        self.thread = None
        self.running = False

    def start(self):
        """Start the worker thread."""
        if self.running:
            return
        self.running = True
        self.thread = threading.Thread(target=self._run, daemon=False)
        self.thread.start()

    def stop(self):
        """Stop the worker thread and wait for it to finish."""
        self.running = False
        if self.thread:
            self.thread.join()

    def _run(self):
        """Main worker loop that processes items from the queue."""
        while self.running:
            try:
                item = self.queue.get(timeout=1)
                self.callback(item)
                self.queue.task_done()
            except queue.Empty:
                continue


# Example usage
if __name__ == "__main__":
    def process_item(item):
        print(f"Processing: {item}")

    worker = QueueWorker(process_item)
    worker.start()

    for i in range(5):
        worker.queue.put(i)

    worker.queue.join()
    worker.stop()
